CustomField.formula:
if( Onboarding_Link__r.Stage_Grouping__c = "Launched", "Launched",
if( Onboarding_Link__r.Stage__c = "", "Launch Not Scheduled: " & Text(Floor( (Today()- Close_Date_Actual__c  )/30 )),
if(Floor( (Onboarding_Link__r.Target_Onboarding_Month_Date__c - Close_Date_Actual__c  )/30 )<1, "Under a Month", 
"Months in Launch: " & Text(Floor( (Onboarding_Link__r.Target_Onboarding_Month_Date__c - Close_Date_Actual__c  )/30 ))
)))
